  constructor() {
    this.sheetId.valueChanges.subscribe(() => this.error.set(''));
  }

  protected async load(): Promise<void> {
    const id = this.sheetId.value.trim();
    this.error.set('');
    if (!id) {
      this.error.set('Type a sheet id to load.');
